<script setup lang="ts">
import { computed, ref } from "vue";
import {
  ArrowDown, ArrowRight, Check, CheckCheck, Circle, Command, Eye,
  FileText, GitBranch, Layers3, Palette, RotateCcw, Search,
  Sparkles, Terminal, WandSparkles,
} from "@lucide/vue";
import { activeTheme, applyTheme, savedTheme, THEMES, type ThemeId } from "../lib/theme";

const choices = THEMES.filter((theme) => theme.id !== "original");
const message = ref("");
const isPreview = computed(() => activeTheme.value !== savedTheme.value);
const activeName = computed(() => THEMES.find((theme) => theme.id === activeTheme.value)?.name);
const savedName = computed(() => THEMES.find((theme) => theme.id === savedTheme.value)?.name);

function preview(id: ThemeId) {
  applyTheme(id, false);
  message.value = "已临时应用到整个工作台。可以切换页面查看；刷新后恢复已保存的风格。";
}

function adopt(id: ThemeId) {
  message.value = applyTheme(id)
    ? "已保存此风格，下次打开工作台时会继续使用。"
    : "当前风格已应用，但浏览器未能保存偏好；刷新后可能恢复原来的选择。";
}

function restore() {
  applyTheme(savedTheme.value, false);
  message.value = "已退出临时预览，恢复你之前保存的风格。";
}
</script>

<template>
  <div class="theme-gallery">
    <header class="gallery-intro">
      <div>
        <span class="gallery-kicker"><Palette :size="13" /> DESIGN STUDIO / 01</span>
        <h1>配色与材质，<br class="gallery-mobile-break" /><span>也可以按你喜欢的来。</span></h1>
        <p>这里调整颜色和材质。不同的页面布局、功能组织和交互，请到 <RouterLink to="/gallery">工作模式</RouterLink> 直接体验。</p>
      </div>
      <a class="gallery-jump" href="#theme-choices" aria-label="查看三种风格"><ArrowDown :size="19" /></a>
    </header>

    <div class="theme-status" aria-live="polite" aria-atomic="true">
      <span class="theme-status-icon"><Eye v-if="isPreview" :size="18" /><CheckCheck v-else :size="18" /></span>
      <div>
        <strong>{{ isPreview ? '临时预览' : '当前风格' }} · {{ activeName }}</strong>
        <p>已保存：{{ savedName }}。只有“采用此风格”会覆盖保存的选择。</p>
      </div>
      <button v-if="isPreview" class="gallery-button gallery-button-quiet" @click="restore"><RotateCcw :size="14" />退出预览</button>
    </div>
    <p v-if="message" class="gallery-feedback" role="status">{{ message }}</p>

    <section id="theme-choices" class="theme-choices" aria-label="选择视觉风格">
      <article v-for="theme in choices" :key="theme.id" class="theme-card" :class="`theme-card-${theme.id}`">
        <div class="theme-art" :class="`art-${theme.id}`" role="img" :aria-label="`${theme.name} 的静态界面风格示意，不是实际运行数据`">
          <span class="art-caption">静态风格预览</span>

          <template v-if="theme.id === 'aurora'">
            <div class="aurora-grain"></div>
            <div class="aurora-orbit orbit-one"></div><div class="aurora-orbit orbit-two"></div>
            <div class="aurora-topline"><span class="mini-brand"><Sparkles :size="16" /> SANJIU / STUDIO</span><span class="mini-key"><Command :size="10" /> K</span></div>
            <div class="aurora-layout">
              <div class="aurora-copy"><span class="art-eyebrow">YOUR IDEAS, CONNECTED</span><h2>让每个想法，<br />开始流动。</h2><p>从一份文档，到一个可解释的回答。</p><span class="art-action">进入工作空间 <ArrowRight :size="13" /></span></div>
              <div class="aurora-canvas">
                <div class="aurora-core"><div><WandSparkles :size="30" /><span>Agent</span></div></div>
                <div class="floating-node node-document"><span><FileText :size="16" /></span><div><strong>工程文档</strong><small>Knowledge source</small></div></div>
                <div class="floating-node node-flow"><span><GitBranch :size="16" /></span><div><strong>工作流</strong><small>Ideas into actions</small></div></div>
                <div class="floating-node node-answer"><span><Sparkles :size="16" /></span><div><strong>有据可循</strong><small>Context matters</small></div></div>
                <svg class="aurora-paths" viewBox="0 0 340 230" fill="none" aria-hidden="true"><path d="M90 55C145 55 112 112 170 112M250 48C205 48 225 112 170 112M170 112C238 112 202 183 264 183" /></svg>
              </div>
            </div>
            <div class="aurora-bottom"><span><i></i> 想法 · 资料 · 行动</span><span>BUILT TO EXPLORE <ArrowRight :size="10" /></span></div>
          </template>

          <template v-else-if="theme.id === 'graphite'">
            <div class="terminal-top"><span><Terminal :size="13" /> SANJIU / CONTROL</span><span class="terminal-dots"><i></i><i></i><i></i></span></div>
            <div class="terminal-layout"><div class="terminal-rail"><Command :size="15" /><GitBranch :size="15" /><Layers3 :size="15" /><span>01</span></div><div class="terminal-content"><span class="art-eyebrow">FOCUS MODE</span><h2>少一点干扰。<br /><span>多一点掌控。</span></h2><div class="terminal-row"><span>01</span><span>读取上下文</span><span class="terminal-rule"></span><FileText :size="12" /></div><div class="terminal-row"><span>02</span><span>查看执行过程</span><span class="terminal-rule"></span><GitBranch :size="12" /></div><div class="terminal-prompt"><span>›</span> 在这里，专注下一步<span class="terminal-cursor"></span></div></div></div>
            <span class="terminal-watermark" aria-hidden="true">[ G ]</span>
          </template>

          <template v-else>
            <div class="glacier-glow"></div>
            <div class="glacier-top"><span><Layers3 :size="15" /> SANJIU SPACE</span><span class="glacier-avatar">玖</span></div>
            <div class="glacier-layout"><div class="glacier-copy"><span class="art-eyebrow">A LITTLE MORE CLARITY</span><h2>给思考，<br />留一点空间。</h2><span class="glacier-search"><Search :size="12" /> 找到值得留下的答案</span></div><div class="glacier-stack"><div class="glass-back"></div><div class="glass-note"><span class="glass-file"><FileText :size="19" /></span><small>MY KNOWLEDGE</small><strong>让知识<br />清晰可见</strong><span class="glass-line"></span><span class="glass-line short"></span><div class="glass-note-bottom"><span>一页新的可能</span><ArrowRight :size="13" /></div></div><div class="glass-chip"><Sparkles :size="12" /> 轻盈，也有条理</div></div></div>
          </template>
        </div>

        <div class="theme-card-info">
          <div class="theme-name-line"><h2>{{ theme.name }}</h2><span v-if="theme.id === 'aurora'" class="theme-recommend"><Sparkles :size="11" />推荐</span><span v-if="savedTheme === theme.id" class="theme-saved"><Check :size="11" />已采用</span></div>
          <p>{{ theme.description }}</p>
          <div class="theme-card-bottom"><span class="theme-palette" :class="`palette-${theme.id}`" aria-hidden="true"><i></i><i></i><i></i><i></i></span><div class="theme-actions"><button class="gallery-button gallery-preview" :aria-pressed="activeTheme === theme.id" @click="preview(theme.id)"><Eye :size="14" />预览此风格</button><button class="gallery-button gallery-adopt" :disabled="savedTheme === theme.id && activeTheme === theme.id" @click="adopt(theme.id)">{{ savedTheme === theme.id && activeTheme === theme.id ? '已采用' : '采用此风格' }}<ArrowRight :size="13" /></button></div></div>
        </div>
      </article>
    </section>

    <div class="original-theme">
      <span class="original-swatch" aria-hidden="true"><Circle :size="20" /></span><div><strong>也可以，保持熟悉的样子。</strong><p>原版森系工作台始终保留，随时都能回来。</p></div><div class="original-actions"><button class="gallery-button gallery-button-quiet" @click="preview('original')">预览原版</button><button class="gallery-button gallery-button-quiet" :disabled="savedTheme === 'original' && activeTheme === 'original'" @click="adopt('original')">{{ savedTheme === 'original' && activeTheme === 'original' ? '当前为原版' : '恢复并保存原版' }}</button></div>
    </div>
    <p class="gallery-footnote">卡片中的内容仅用于展示设计，不代表实际运行状态。切换风格不改变项目数据和后端连接。</p>
  </div>
</template>

